/* ============ STATE & ROUTING ============ */
let role='presales', realRole='presales', cur={view:'home', prod:null, cat:'overview'};
let lang='en'; try{lang=localStorage.getItem('hub-lang')||'en'}catch(e){}
const L=(en,ar)=>lang==='ar'&&ar!=null?ar:en;
const PT=(p,k)=>lang==='ar'&&PROD_AR[p.id]&&PROD_AR[p.id][k]!=null?PROD_AR[p.id][k]:p[k];
const catName=c=>lang==='ar'?CAT_AR[c.id][0]:c.name, catDesc=c=>lang==='ar'?CAT_AR[c.id][1]:c.desc;
function setLang(l){lang=l;try{localStorage.setItem('hub-lang',l)}catch(e){}if(!window._appStarted){location.reload();return}applyLang();render()}
function applyLang(){document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.body.classList.toggle('rtl',lang==='ar');
 $('#lEn').classList.toggle('on',lang==='en');$('#lAr').classList.toggle('on',lang==='ar');$('#q').placeholder=L('Search features, objections, RFP answers…','ابحث في الميزات والاعتراضات وإجابات المنافسات…');
renderRoleBadge();$('#hubName').textContent=L('Presales Hub','مركز ما قبل البيع');document.title=L('IIH Presales Hub','مركز ما قبل البيع - IIH')}
const arNote=()=>lang==='ar'?`<div class="note-info">ℹ هذا القسم متاح حالياً باللغة الإنجليزية، وستتم إضافة الترجمة العربية.</div>`:'';
const $=s=>document.querySelector(s), main=$('#main'), sr=$('#sr');
const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));

const SHOWCASE=location.origin+location.pathname.replace(/[^/]*$/,'')+'showcase/';
const ROLES={leadership:['Leadership','القيادة'],lead:['Presales lead','قائد ما قبل البيع'],presales:['Presales','ما قبل البيع'],client:['Client view','عرض العميل']};
const INTERNAL_CATS=['icp','pains','compete','objections','pricing','qualify'];
function setRole(r,silent){role=r;document.body.classList.toggle('admin',r==='leadership');document.body.classList.toggle('client',r==='client');renderRoleBadge();if(!silent)toast(L('Viewing as','العرض كـ')+': '+L(...ROLES[r]));
  if(r==='client'&&!['home','product'].includes(cur.view))go('home');else if(cur.view==='product'&&r==='client'&&INTERNAL_CATS.includes(cur.cat))go('product',cur.prod);else render();}
function previewRole(r){setRole(r)}
function renderRoleBadge(){const b=document.getElementById('roleBadge');if(!b)return;b.textContent=L('Your access','صلاحيتك')+': '+L(...ROLES[realRole]);if(!document.getElementById('soBtn')){const so=document.createElement('button');so.id='soBtn';so.className='so';so.onclick=()=>signOut();document.getElementById('accBadge').appendChild(so)}document.getElementById('soBtn').textContent=L('Sign out','خروج');
  const s=document.getElementById('previewAs');if(realRole==='leadership'){s.style.display='';s.innerHTML=Object.keys(ROLES).map(k=>`<option value="${k}" ${k===role?'selected':''}>${L('Preview as','عرض كـ')} ${L(...ROLES[k])}</option>`).join('')}else s.style.display='none';}
function go(view,prod,cat){if(view==='lead'&&cur.prod!==prod){leadDraft=null;leadTab='overview'}cur={view,prod:prod||null,cat:cat||'overview'};const h=view==='product'?prod+(cat&&cat!=='overview'?'-'+cat:''):view==='lead'?'lead-'+prod:view;if(location.hash.slice(1)!==h)history.replaceState(null,'','#'+h);render();window.scrollTo(0,0);}
function fromHash(){const h=location.hash.slice(1);if(!h||h==='home')return go('home');if(['templates','users','setup','finder','leads','exec'].includes(h))return go(h);if(h.startsWith('lead-'))return go('lead',h.slice(5));const [p,...c]=h.split('-');if(PRODUCTS.find(x=>x.id===p))return go('product',p,c.join('-')||'overview');go('home');}
window.addEventListener('hashchange',fromHash);

function renderTabs(){
  let t=`<button class="tab ${cur.view==='home'||cur.view==='product'?'on':''}" onclick="go('home')">⌂ ${L('Products','المنتجات')}</button>`;
  if(role==='client'){$('#tabs').innerHTML=t;return}
  if(role==='leadership'&&realRole==='leadership')t+=`<button class="tab ${cur.view==='exec'?'on':''}" onclick="go('exec')" style="font-weight:700">★ ${L('Leadership','القيادة')}</button>`;
  t+=`<button class="tab ${cur.view==='leads'||cur.view==='lead'?'on':''}" onclick="go('leads')">◈ ${L('Leads','الفرص')}${LEADS.length?` <span class="n">${LEADS.length}</span>`:''}</button>`;
  t+=`<button class="tab ${cur.view==='finder'?'on':''}" onclick="go('finder')">◎ ${L('Product finder','مكتشف المنتج')}</button>`;
  t+=`<button class="tab ${cur.view==='templates'?'on':''}" onclick="go('templates')">▤ ${L('Templates','القوالب')}</button>`;
  t+=`<button class="tab util ${cur.view==='users'?'on':''}" onclick="go('users')">🔐 ${L('Access levels','مستويات الوصول')}</button>`;
  t+=`<button class="tab ${cur.view==='setup'?'on':''}" onclick="go('setup')">ⓘ ${L('How it works','آلية العمل')}</button>`;
  $('#tabs').innerHTML=t;
}
function render(){renderTabs();main.innerHTML=({exec:vExec,leads:vLeads,lead:vLead,home:vHome,finder:vFinder,product:vProduct,templates:vTemplates,users:vUsers,setup:vSetup}[cur.view])();if(cur.view==='product'&&cur.cat==='qualify')score();}

/* ============ VIEWS ============ */
function logoImg(p,h){return `<img src="${LOGOS[p.logo]}" alt="${esc(p.name)} logo" style="height:${h}px;max-width:100%;object-fit:contain;display:block">`}
function pcard(p,big){const own=p.logo!=='qiyas';return `<div class="card prod-card pc ${big?'big':''}" style="--c:${p.color}" onclick="go('product','${p.id}')">
   <div class="pc-logo">${logoImg(p,big?64:own?56:34)}</div>
   <div class="pc-body"><div class="pc-cat">${esc(PT(p,'cat'))}</div>
   <h3>${esc(p.name)}</h3><p class="muted small">${esc(PT(p,'tagline'))}</p>
   <div class="pc-go">${p.videos.some(v=>v.src)?'▶ '+L('Video','فيديو')+' · ':''}${L('Open product →','افتح المنتج ←')}</div></div></div>`}
function vHome(){
  const by=id=>PRODUCTS.find(p=>p.id===id), core=['mape','hasad','pulse','uno'].map(by), extra=PRODUCTS.filter(p=>['agent','datahub'].includes(p.id)), other=PRODUCTS.filter(p=>!['cockpit','mape','hasad','pulse','uno','agent','datahub'].includes(p.id));
  return `
  <div class="home-head"><img src="assets/iih.png" alt="Ideal Innovation House" class="iih-logo"><div class="hh-txt"><span class="pill gold">${L('Presales Knowledge Base','قاعدة معرفة ما قبل البيع')}</span><h1 style="margin-top:8px">${L('IIH product portfolio','محفظة منتجات IIH')}</h1><p class="muted">${L('Choose a product to open its presales kit: pitch, personas, discovery questions, features, demo videos, technical answers and more.','اختر منتجاً لفتح ملف ما قبل البيع الخاص به: العرض المختصر والشخصيات وأسئلة الاستكشاف والميزات وفيديوهات العرض والإجابات التقنية وغيرها.')}</p></div>
   <button class="btn" onclick="go('leads')">◈ ${L('Leads','الفرص')}</button></div>
  <div class="brand-sec"><img src="${LOGOS.qiyas}" alt="Qiyas AI" style="height:34px"><span>${L('Qiyas AI product family','عائلة منتجات قياس AI')}</span><span style="flex:1"></span>
   <a class="intro-link" href="javascript:playIntro()"><span class="pl">▶</span><span><b>${L('Watch: Introduction to the Qiyas products','شاهد: مقدمة عن منتجات قياس')}</b><small>${L('3:56 · all four products in one video','3:56 · المنتجات الأربعة في فيديو واحد')}</small></span></a></div>
  <div class="group-hd"><b>${L('Four integrated products','أربعة منتجات متكاملة')}</b><span>${L('Qiyas MAPE, Qiyas HASSAD, Qiyas Pulse and Qiyas Uno are integrated with each other and share one AI layer, so insight carries across strategy, hours, feedback and operations.','تتكامل Qiyas MAPE وQiyas HASSAD وQiyas Pulse وQiyas Uno مع بعضها وتشترك في طبقة ذكاء اصطناعي واحدة، فتنتقل الرؤى بين الاستراتيجية وساعات العمل والملاحظات والعمليات.')}</span></div>
  <div class="grid g4">${core.map(p=>pcard(p)).join('')}</div>
  <div class="group-hd"><b>${L('Intelligence layer','طبقة الذكاء')}</b><span>${L('Qiyas Cockpit reads the signals from the four integrated products.','يقرأ Qiyas Cockpit الإشارات من المنتجات الأربعة المتكاملة.')}</span></div>
  ${pcard(by('cockpit'),true)}
  <div class="group-hd"><b>${L('Platform capabilities','قدرات المنصة')}</b><span>Qiyas Agent ${L('and','و')} Qiyas Data Hub.</span></div>
  <div class="grid g2">${extra.map(p=>pcard(p)).join('')}</div>
  ${other.length?`<div class="brand-sec" style="margin-top:34px"><span style="font-family:var(--serif);font-size:20px;color:var(--navy)">${L('More IIH products','منتجات أخرى من IIH')}</span></div>
  <div style="margin-top:14px">${other.map(p=>pcard(p,true)).join('')}</div>`:''}`;
}
function playIntro(){$('#mt').textContent=L('Introduction to the Qiyas products','مقدمة عن منتجات قياس');$('#mb').innerHTML=`<video controls autoplay preload="metadata" poster="videos/qiyas-intro-poster.jpg" style="width:100%;border-radius:8px;background:#000"><source src="videos/qiyas-intro.mp4" type="video/mp4"></video><p class="small muted">${L('Qiyas MAPE, Qiyas HASSAD, Qiyas Pulse and Qiyas Uno, and how they connect. English.','Qiyas MAPE وQiyas HASSAD وQiyas Pulse وQiyas Uno وكيف تترابط. باللغة الإنجليزية.')}</p>`;$('#modal').classList.add('show');}
function vFinder(){return `<h1>${L('Product finder','مكتشف المنتج')}</h1><p class="muted">${L('Tick what you heard in the first call to see which product to lead with.','حدد ما سمعته في الاتصال الأول لمعرفة المنتج الذي تبدأ به.')}</p>${arNote()}
  <div class="grid g2"><div class="card"><div class="fit-opt" id="fit">${Object.keys(FIT).map(o=>`<button onclick="this.classList.toggle('on');fit()">${o}</button>`).join('')}</div>
     <div id="fitRes" class="muted small">${L('Select at least one signal.','اختر إشارة واحدة على الأقل.')}</div></div>
   <div class="card"><h3>${L('Content gaps to close','فجوات المحتوى')}</h3><p class="muted small">${L('What presales still needs from each product owner.','ما يحتاجه فريق ما قبل البيع من مالك كل منتج.')}</p><div class="feed">${PRODUCTS.map(p=>{const miss=[[p.videos.length,'demo videos'],[p.cases.length,'success stories'],[p.comp.length,'battle cards'],[p.obj.length,'objections'],[p.tiers.length,'pricing'],[p.rfp.length,'RFP answers']].filter(x=>!x[0]).map(x=>x[1]);return `<div style="cursor:pointer" onclick="go('product','${p.id}')"><span class="ico" style="background:${p.color};color:#fff;font-size:11px;font-weight:700">${p.ini}</span><div><b>${esc(p.name)}</b> — ${miss.length?'missing '+miss.join(', '):'complete'}<br><span class="small muted">${esc(p.owner)}</span></div></div>`}).join('')}</div></div></div>`;}
const FIT={'Leaders lack one view of performance':['cockpit','agent'],'Strategy not linked to employee goals':['mape'],'Performance reviews are painful':['mape','pulse'],'Timesheet / utilisation problems':['hasad'],'Payroll, WPS or GOSI effort':['hasad','uno'],'Burnout or attrition worries':['hasad','cockpit'],'Unread feedback / low survey response':['pulse'],'Running on spreadsheets / many systems':['uno'],'Leaders wait days for data answers':['agent'],'Must keep current ERP (SAP, Oracle…)':['datahub','mape'],'High volume of job applications':['orbit'],'Slow or inconsistent hiring':['orbit'],'Recruiting across HQ and many units':['orbit'],'Strong past candidates get lost':['orbit']};
function fit(){
  const on=[...document.querySelectorAll('#fit button.on')].map(b=>b.textContent);
  const sc={};on.forEach(o=>FIT[o].forEach(id=>sc[id]=(sc[id]||0)+1));
  const best=Object.entries(sc).sort((a,b)=>b[1]-a[1]);
  $('#fitRes').innerHTML=!best.length?'Select at least one signal.':best.map(([id,n],i)=>{const p=PRODUCTS.find(x=>x.id===id);return `<div style="display:flex;align-items:center;gap:10px;margin:6px 0"><span class="dot" style="width:10px;height:10px;border-radius:50%;background:${p.color};display:inline-block"></span><b style="color:var(--navy)">${esc(p.short)}</b><span class="pill ${i===0?'green':''}">${n} signal${n>1?'s':''}</span><button class="btn" style="margin-inline-start:auto" onclick="go('product','${id}','pains')">${L('Open discovery →','افتح أسئلة الاستكشاف ←')}</button></div>`}).join('');
}

function vProduct(){
  const p=PRODUCTS.find(x=>x.id===cur.prod), c=CATS.find(x=>x.id===cur.cat);
  const count=id=>({overview:1,icp:p.personas.length,pains:p.pains.length,features:p.features.length,demo:p.videos.length+p.shots.length,cases:p.cases.length,compete:p.comp.length,objections:p.obj.length,pricing:p.tiers.length,tech:p.tech.length,qualify:1,assets:p.rfp.length})[id];
  let tabs='',g='';CATS.filter(k=>role!=='client'||!INTERNAL_CATS.includes(k.id)).forEach(k=>{if(k.g!==g){g=k.g;tabs+=`<span class="pt-grp">${L(g,CATG_AR[g])}</span>`}const n=count(k.id);tabs+=`<button class="pt ${k.id===cur.cat?'on':''} ${n?'':'empty-t'}" onclick="go('product','${p.id}','${k.id}')">${catName(k)}${n&&!['overview','qualify'].includes(k.id)?` <span class="n">${n}</span>`:''}</button>`});
  return `
  <button class="back" onclick="go('home')">${L('← All products','→ كل المنتجات')}</button>
  <div class="viewer-note">👁 ${L('You have <b>read-only</b> access. You can view, search, copy and share links.','لديك صلاحية <b>قراءة فقط</b>. يمكنك العرض والبحث والنسخ ومشاركة الروابط.')}</div>
  <div class="prod-head card" style="border-top:4px solid ${p.color};align-items:center">
    <div style="width:${p.logo!=='qiyas'?220:150}px;flex:none">${logoImg(p,p.logo!=='qiyas'?72:38)}</div>
    <div style="flex:1;border-inline-start:1px solid var(--line);padding-inline-start:20px"><div class="pc-cat">${esc(PT(p,'cat'))}</div><h1>${esc(p.name)}</h1><div class="muted">${esc(PT(p,'tagline'))}</div>
    <div class="meta"><span class="pill ${p.status==='GA'?'green':'orange'}">${p.status}</span><span class="pill gold int">${L('Draft','مسودة')}</span><span class="int">${L('Owner','المالك')}: ${esc(p.owner)}</span><span class="int">${L('Readiness','الجاهزية')}: <b>${p.ready}%</b></span></div></div>
    <div style="display:flex;flex-direction:column;gap:8px"><button class="btn admin-only" onclick="toast(L('Editor would open here (admin / editor only)','سيفتح المحرر هنا (للمسؤول والمحرر فقط)'))">✎ ${L('Edit product','تعديل المنتج')}</button>
    <button class="btn" onclick="copyText(location.href,L('Link copied','تم نسخ الرابط'))">🔗 ${L('Share link','مشاركة الرابط')}</button></div></div>
  <div class="ptabs">${tabs}</div>
  ${role==='client'?`<div class="client-bar">👁 ${L('Client view preview: internal sections (buyer profiles, discovery, battle cards, objections, pricing, qualification) and draft notes are hidden. Real clients get the separate Product Showcase link.','معاينة عرض العميل: الأقسام الداخلية (الشخصيات، الاستكشاف، المنافسة، الاعتراضات، التسعير، التأهيل) والملاحظات المبدئية مخفية. العملاء الفعليون يحصلون على رابط عرض المنتجات المنفصل.')}</div>`:''}<div class="viewer-note draft-note" style="display:block;background:#EEF2F5;border-color:var(--line);color:var(--navy-2)">✎ <b>${L('Draft content','محتوى مبدئي')}</b> — ${lang==='ar'?(p.source?'مبني على وثائق منتج Orbit HR (13 نوفمبر 2026) وعرض الميزات، وتفاصيل الاستضافة والتنفيذ من عرض وزارة الثقافة. يراجعه مالك المنتج قبل استخدامه.':'مكتوب من موقع قياس العام (qiyas.ai). يراجعه مالك المنتج قبل استخدامه. اللقطات توضيحية.'):(p.source?esc(p.source):'written from the public Qiyas AI website (qiyas.ai, 14 Nov 2026). Product owner to validate before presales use. Screenshots are placeholders.')}</div>
  <section><div class="sec-title"><h2>${catName(c)}</h2>${c.id==='pricing'?`<span class="pill wine">${L('Internal only','داخلي فقط')}</span>`:''}<span style="flex:1"></span><button class="btn int" onclick="feedbackForm('${p.id}','${c.id}')">📝 ${L('Report an issue','إبلاغ عن ملاحظة')}</button><button class="btn admin-only" onclick="openTpl('${tplFor(c.id)}')">＋ ${L('Add from template','إضافة من قالب')}</button></div>
   <p class="sec-desc">${catDesc(c)}</p>${['overview','qualify'].includes(c.id)?'':arNote()}${sec(p,c.id)}
   <div class="meta int" style="border-top:1px solid var(--line);padding-top:10px;margin-top:20px"><span>${L('Source','المصدر')}: ${p.source?L('Orbit HR Product Documentation (13 Nov 2026) & Features deck','وثائق منتج Orbit HR (13 نوفمبر 2026) وعرض الميزات'):'qiyas.ai (14 Nov 2026)'}</span><span>${L('Status: draft — awaiting product owner review','الحالة: مسودة بانتظار مراجعة مالك المنتج')}</span></div></section>`;
}
function tplFor(c){return ({features:'feature',compete:'battle',objections:'objection',demo:'demo',cases:'case',pains:'discovery',assets:'rfp'})[c]||'onepager';}
const none=()=>`<div class="empty">${L('No content yet.','لا يوجد محتوى بعد.')} <span class="admin-only" style="display:inline">${L('Use “Add from template” to create the first entry.','استخدم "إضافة من قالب" لإنشاء أول إدخال.')}</span></div>`;
function vidCard(p,v,i,big){return `<div class="card vcard" style="padding:0;overflow:hidden"><video id="vid${p.id}${i}" controls preload="metadata" poster="${v.poster}" style="width:100%;display:block;background:#000;aspect-ratio:16/9"><source src="${v.src}" type="video/mp4"></video><div style="padding:12px 14px"><b style="color:var(--navy)">${esc(v.t)}</b> <span class="small muted">· ${v.d} · ${esc(lang==='ar'&&v.aAr?v.aAr:v.a)}</span>${v.ch&&v.ch.length?`<div class="label">${L('Jump to','انتقل إلى')}</div><div class="chap" ${v.rtl?'dir="rtl"':''}>${v.ch.map(c=>`<button onclick="seek('${p.id}${i}',${c[0]})">${Math.floor(c[0]/60)}:${String(c[0]%60).padStart(2,'0')} ${esc(c[1])}</button>`).join('')}</div>`:''}</div></div>`}

function sec(p,id){
 switch(id){
 case 'overview': {const fv=p.videos.filter(v=>v.src); return `${fv.length?`<div class="${fv.length>1?'grid g2':''}" style="margin-bottom:14px;${fv.length>1?'':'max-width:720px'}">${fv.map((v,i)=>vidCard(p,v,i)).join('')}</div>`:''}${p.notYet?`<div class="note-warn int" style="font-size:14px">⚠ ${esc(PT(p,'notYet'))}</div>`:''}${p.keyMsg?`<div class="card" style="background:#F5EEF9;border-color:#DCD0F4;margin-bottom:14px"><b style="color:${p.color}">${L('Key message','الرسالة الأساسية')}</b><div style="margin-top:4px">${esc(PT(p,'keyMsg'))}</div></div>`:''}${p.journey?`<div class="card" style="margin-bottom:14px"><div class="label" style="margin-top:0">${L('The journey','الرحلة')}</div><div class="journey">${PT(p,'journey').map((j,i)=>`<span class="jstep" style="--c:${p.color}"><b>${i+1}</b>${esc(j)}</span>`).join(`<span class="jarr">${lang==='ar'?'←':'→'}</span>`)}</div></div>`:''}<div class="card"><div class="label">${L('30-second pitch','العرض المختصر (30 ثانية)')}</div><button class="btn copy" onclick="copyText(${JSON.stringify(PT(p,'pitch')).replace(/"/g,'&quot;')})">⎘ ${L('Copy','نسخ')}</button><div class="pitch">${esc(PT(p,'pitch'))}</div>
   <div class="label">${L('Four things to remember','أربع نقاط للتذكر')}</div><div class="grid g2" style="margin-top:6px">${PT(p,'elevator').map((e,i)=>`<div style="display:flex;gap:10px;align-items:center;background:var(--soft);padding:10px 12px;border-radius:8px"><b style="color:${p.color};font-family:var(--serif);font-size:20px">${i+1}</b>${esc(e)}</div>`).join('')}</div></div>
   <div class="grid g3 int" style="margin-top:16px"><div class="card" onclick="go('product','${p.id}','demo')" style="cursor:pointer"><b>▶ ${L('Demo kit','عدة العرض')}</b><p class="small muted">${L('Videos, screenshots and the demo script.','الفيديوهات واللقطات وسيناريو العرض.')}</p></div><div class="card" onclick="go('product','${p.id}','pains')" style="cursor:pointer"><b>! ${L('Prepare discovery','جهّز أسئلة الاستكشاف')}</b><p class="small muted">${L('Questions for your first meeting.','أسئلة لاجتماعك الأول.')}</p></div><div class="card" onclick="go('leads')" style="cursor:pointer"><b>◈ ${L('Track a lead','تابع فرصة')}</b><p class="small muted">${L('Add the client to Leads with this product.','أضف العميل إلى الفرص مع هذا المنتج.')}</p></div></div>`;}
 case 'icp': return `<div class="grid g4" style="margin-bottom:16px">${[['Company size',p.icp.size],['Sectors',p.icp.sector],['Buying triggers',p.icp.trigger],['Budget usually from',p.icp.budget]].map(([a,b])=>`<div class="card"><div class="label" style="margin-top:0">${a}</div>${esc(b)}</div>`).join('')}</div>
   <table class="bc"><tr><th>Persona</th><th>What they care about</th><th>Show them</th></tr>${p.personas.map(x=>`<tr><td>${esc(x.r)}</td><td>${esc(x.c)}</td><td>${esc(x.s)}</td></tr>`).join('')}</table>`;
 case 'pains': return p.pains.length?`<p class="small muted">Tick questions as you ask them, then copy the list into your meeting notes.</p>${p.pains.map(x=>`<label class="q"><input type="checkbox"><div><b>${esc(x.q)}</b><small>Uncovers: ${esc(x.p)}</small></div></label>`).join('')}<button class="btn primary" style="margin-top:8px" onclick="copyText(${JSON.stringify(p.pains.map((x,i)=>(i+1)+'. '+x.q).join('\n')).replace(/"/g,'&quot;')},'Questions copied')">⎘ Copy all questions</button>`:none();
 case 'features': return p.features.length?`<div class="feat-hd"><span>Feature</span><span>Business benefit (lead with this)</span><span>Proof</span></div>${p.features.map(x=>`<div class="feat"><div><b style="color:var(--navy)">${esc(x.f)}</b></div><div>${esc(x.b)}</div><div><span class="pill green">✓</span> <span class="small">${esc(x.p)}</span></div></div>`).join('')}`:none();
 case 'demo': return `<h3 style="font-size:17px">${L('Videos','الفيديوهات')}</h3>${p.videos.length?(p.videos[0].src?`<div class="grid g2" style="margin-bottom:22px">${p.videos.map((v,i)=>vidCard(p,v,'d'+i)).join('')}</div>`:`<div class="grid g3" style="margin-bottom:22px">${p.videos.map((v,i)=>`<div class="shot video" onclick="openShot('${p.id}','dash','${esc(v.t)}',true)">${mock('dash',p.color)}<div class="play"><i><svg width="18" height="18" viewBox="0 0 24 24" fill="#fff"><path d="M8 5v14l11-7z"/></svg></i></div><span class="dur">${v.d}</span><div class="cap"><b>${esc(v.t)}</b>${esc(v.a)}</div></div>`).join('')}</div>`):none()}
   <h3 style="font-size:17px">${L('Screenshots','لقطات الشاشة')}</h3><div class="grid g4" style="margin-bottom:22px">${p.shots.map((s,i)=>s.img?`<div class="shot" onclick="openImg('${p.id}',${i})"><img src="${s.img}" alt="${esc(s.t)}" style="width:100%;aspect-ratio:16/9;object-fit:${s.fit||'cover'};background:#fff;display:block"><div class="cap"><b>${esc(s.t)}</b>${esc(s.n)}</div></div>`:`<div class="shot" onclick="openShot('${p.id}','${s.k}','${esc(s.t)}')">${mock(s.k,p.color)}<div class="cap"><b>${esc(s.t)}</b>Placeholder — add real screenshot</div></div>`).join('')}</div>
   <h3 style="font-size:17px">${L('Demo click-path','سيناريو العرض')}</h3>${p.demoScript.length?`<div class="card"><ol style="margin:0;padding-left:20px">${p.demoScript.map((s,i)=>`<li style="padding:5px 0">${esc(s)} ${i===1?'<span class="pill orange">wow moment</span>':''}</li>`).join('')}</ol></div>`:none()}`;
 case 'cases': return p.cases.length?`<div class="grid g2">${p.cases.map(x=>`<div class="card"><span class="pill gold">${esc(x.ref)}</span><h3 style="margin-top:8px">${esc(x.c)}</h3><p class="muted">${esc(x.o)}</p><div style="display:flex;gap:10px;flex-wrap:wrap">${x.r.map(r=>`<div style="background:var(--soft);border-radius:8px;padding:10px 12px;font-weight:700;color:var(--navy)">${esc(r)}</div>`).join('')}</div></div>`).join('')}</div>`:none();
 case 'compete': return p.comp.length?p.comp.map(x=>`<details class="acc" open><summary>vs ${esc(x.x)}</summary><div class="body"><div class="label">Where we win</div><span class="win">▲</span> ${esc(x.w)}<div class="label">Where we lose</div><span class="lose">▼</span> ${esc(x.l)}<div class="label">Landmine question</div><i>${esc(x.m)}</i></div></details>`).join(''):none();
 case 'objections': return p.obj.length?p.obj.map(x=>`<details class="acc"><summary>${esc(x.o)}</summary><div class="body"><div class="label">Response</div>${esc(x.r)} <button class="btn" style="margin-left:6px;padding:3px 10px" onclick="copyText(${JSON.stringify(x.r).replace(/"/g,'&quot;')})">⎘</button><div class="label">Proof to send</div><span class="pill">${esc(x.p)}</span></div></details>`).join(''):none();
 case 'pricing': return !p.tiers.length&&p.disc?`<div class="card" style="background:#FFF8E6;border-color:#F0DDA6">${esc(p.disc)}</div>`:p.tiers.length?`<div class="tier">${p.tiers.map(t=>`<div class="card ${t.best?'best':''}">${t.best?'<span class="pill green">Most sold</span>':''}<h3 style="margin-top:6px">${esc(t.n)}</h3><div class="muted small">${esc(t.p)}</div><ul style="padding-left:18px;margin:10px 0 0">${t.i.map(i=>`<li>${esc(i)}</li>`).join('')}</ul></div>`).join('')}</div><div class="card" style="margin-top:14px;background:#FFF8E6;border-color:#F0DDA6"><b>Discount guardrails:</b> ${esc(p.disc)}</div>`:none();
 case 'tech': return `<table class="bc"><tr><th>Area</th><th>Answer</th></tr>${p.tech.filter(([k])=>role!=='client'||!/Not in production|MoC proposal/.test(k)).map(([a,b])=>`<tr><td>${esc(a)}</td><td>${esc(b)}</td></tr>`).join('')}</table>`;
 case 'qualify': return qualify();
 case 'assets': return (p.rfp.length?p.rfp.map(x=>`<div class="card" style="margin-bottom:10px"><button class="btn copy" onclick="copyText(${JSON.stringify(x.a).replace(/"/g,'&quot;')},'Answer copied')">⎘ Copy</button><b style="color:var(--navy)">${esc(x.q)}</b><p style="margin:8px 0 0">${esc(x.a)}</p><div class="meta"><span class="pill green">Approved</span><span>Legal & Product · Oct 2026</span></div></div>`).join(''):none())+
   `<h3 style="font-size:17px;margin-top:18px">Downloadable assets</h3><div class="grid g4">${['Product one-pager (EN/AR)','Pitch deck','Security & compliance pack','ROI calculator'].map(a=>`<div class="card small"><b>📄 ${a}</b><div class="muted">Link to SharePoint / storage</div></div>`).join('')}</div>`;
 }
}
const QF=[['Pain','Clear, admitted business pain','الألم','مشكلة واضحة يعترف بها العميل'],['Authority','We met the decision maker','الصلاحية','قابلنا صاحب القرار'],['Budget','Budget identified or programme funded','الميزانية','ميزانية محددة أو برنامج ممول'],['Timeline','Decision within 6 months','التوقيت','قرار خلال 6 أشهر'],['Fit','Requirements match our product','الملاءمة','المتطلبات تناسب منتجنا'],['Competition','We are not column-fodder','المنافسة','لسنا مجرد خيار للمقارنة']];
function qualify(){return `<div class="grid g2"><div class="card">${QF.map((q,i)=>`<div class="score-row"><div><b>${L(q[0],q[2])}</b><div class="small muted">${L(q[1],q[3])}</div></div><input type="range" min="0" max="3" value="1" oninput="score()" id="qf${i}"><b id="qv${i}">1</b></div>`).join('')}</div>
 <div class="card" style="text-align:center"><div class="label">${L('Lead score','تقييم الفرصة')}</div><div class="gauge" id="gauge">33%</div><div id="verdict" class="pill orange"></div><p class="small muted" id="advice" style="margin-top:14px"></p><button class="btn primary" onclick="copyText($('#advice').textContent+' '+$('#gauge').textContent,L('Summary copied','تم نسخ الملخص'))">⎘ ${L('Copy summary','نسخ الملخص')}</button></div></div>`;}
function score(){let t=0;QF.forEach((_,i)=>{const v=+$('#qf'+i).value;$('#qv'+i).textContent=v;t+=v});const pct=Math.round(t/18*100);$('#gauge').textContent=pct+'%';const v=$('#verdict'),a=$('#advice');
 if(pct>=70){v.className='pill green';v.textContent=L('Pursue — book demo','تابع — احجز عرضاً');a.textContent=L('Strong lead. Book a tailored demo and bring the success story closest to their sector.','فرصة قوية. احجز عرضاً مخصصاً واستعن بأقرب قصة نجاح لقطاعهم.');}
 else if(pct>=45){v.className='pill gold';v.textContent=L('Qualify further','تحتاج تأهيلاً إضافياً');a.textContent=L('Promising. Before demoing, confirm the weakest areas — usually budget or decision maker.','واعدة. قبل العرض، تأكد من أضعف النقاط — غالباً الميزانية أو صاحب القرار.');}
 else{v.className='pill orange';v.textContent=L('Nurture','رعاية');a.textContent=L('Not ready. Send the one-pager and overview video, and follow up in 60 days.','غير جاهزة. أرسل الملخص والفيديو التعريفي وتابع بعد 60 يوماً.');}}

function vTemplates(){return `<h1>${L('Content templates','قوالب المحتوى')}</h1><p class="muted" style="max-width:760px">${L('Every entry in the knowledge base is created from one of these templates, so all products look the same. Client documents (Scope & Vision, delivery timeline) are generated from the IIH templates inside each lead.','يُنشأ كل إدخال في قاعدة المعرفة من أحد هذه القوالب ليظهر كل منتج بالشكل نفسه. وتُنشأ وثائق العملاء (النطاق والرؤية، والجدول الزمني) من قوالب IIH داخل كل فرصة.')}</p>${arNote()}
 <div class="grid g2" style="margin-bottom:16px"><div class="card" style="display:flex;gap:14px;align-items:center;cursor:pointer" onclick="go('leads')"><img src="assets/iih.png" style="height:34px"><div><b>${L('Scope and Vision document (EN / AR)','وثيقة النطاق والرؤية (عربي / إنجليزي)')}</b><div class="small muted">${L('Open a lead → Scope & Vision → Download Word','افتح فرصة ← النطاق والرؤية ← تنزيل Word')}</div></div></div><div class="card" style="display:flex;gap:14px;align-items:center;cursor:pointer" onclick="go('leads')"><img src="assets/iih.png" style="height:34px"><div><b>${L('Delivery timeline (EN / AR)','الجدول الزمني للتنفيذ (عربي / إنجليزي)')}</b><div class="small muted">${L('Open a lead → Delivery timeline → Download Excel','افتح فرصة ← الجدول الزمني ← تنزيل Excel')}</div></div></div></div>
 <div class="grid g4">${TEMPLATES.map(t=>`<div class="card tpl" onclick="openTpl('${t.id}')"><div class="prev"><div class="ln h"></div><div class="ln o"></div>${t.fields.map(()=>'<div class="ln m"></div><div class="ln s"></div>').join('')}</div><b style="color:var(--navy)">${t.name}</b><div class="small muted">${t.fields.length} fields · ${CATS.find(c=>c.id===t.cat).name}</div></div>`).join('')}</div>`;}
function openTpl(id){const t=TEMPLATES.find(x=>x.id===id);$('#mt').textContent='Template: '+t.name;
 $('#mb').innerHTML=`<p class="muted" style="margin-top:0">${t.use}</p>${t.fields.map(f=>`<div class="field"><label>${f[0]}</label><div class="ph">${f[1]}</div></div>`).join('')}<div class="field"><label>Owner & review date</label><div class="ph">Auto-filled · review reminder every 90 days</div></div><div style="display:flex;gap:8px;justify-content:flex-end"><button class="btn" onclick="closeModal()">Close</button><button class="btn primary admin-only" onclick="closeModal();toast('In the live version this saves to the database')">Use this template</button></div>`;$('#modal').classList.add('show');}

function vUsers(){
  const Y=`<span class="y">✓</span>`,N=`<span class="n">✕</span>`;
  const lv=[['leadership','#6B009D',L('Leadership','القيادة'),L('Admins. Full access to content and leads, assign roles, edit product content.','المسؤولون. وصول كامل للمحتوى والفرص، وتعيين الأدوار، وتعديل محتوى المنتجات.')],
   ['lead','#B700A5',L('Presales lead','قائد ما قبل البيع'),L('All product content plus Leads: add and edit leads, contacts, timeline, scope documents.','كل محتوى المنتجات بالإضافة إلى الفرص: إضافة الفرص وتعديلها وجهات الاتصال والجدول الزمني ووثائق النطاق.')],
   ['presales','#1F8FB3',L('Presales','ما قبل البيع'),L('Read-only product content, including internal sections. No access to leads or client contacts.','قراءة فقط لمحتوى المنتجات بما فيها الأقسام الداخلية. لا وصول إلى الفرص أو بيانات العملاء.')],
   ['client','#25A27F',L('Client (read-only)','العميل (قراءة فقط)'),L('No sign-in. Uses the public Product Showcase, which holds client-safe content only.','بدون تسجيل دخول. يستخدم صفحة عرض المنتجات العامة التي تحتوي على المحتوى المناسب للعملاء فقط.')]];
  const rows=[[L('Product overview, features, videos, screenshots','نظرة عامة، الميزات، الفيديوهات، اللقطات'),Y,Y,Y,Y],[L('Internal sections: buyer profiles, discovery, battle cards, objections, pricing, qualification','الأقسام الداخلية: الشخصيات، الاستكشاف، المنافسة، الاعتراضات، التسعير، التأهيل'),Y,Y,Y,N],[L('Leads, client contacts, forecast','الفرص وبيانات العملاء والتوقعات'),Y,Y,N,N],[L('Add / edit leads, timeline, scope documents','إضافة/تعديل الفرص والجدول الزمني ووثائق النطاق'),Y,Y,N,N],[L('Report content issues','الإبلاغ عن ملاحظات المحتوى'),Y,Y,Y,N],[L('Assign roles, approve sign-ups, edit product content','تعيين الأدوار واعتماد التسجيلات وتعديل المحتوى'),Y,N,N,N]];
  setTimeout(loadAdmin,0);
  return `<h1>${L('Access levels','مستويات الوصول')}</h1><p class="muted" style="max-width:840px">${L('People sign in with their work e-mail and a password, after verifying the e-mail. New sign-ups wait as Pending until Leadership gives them a role below. The database enforces every level, so content a role cannot see is never sent to their browser.','يسجّل الأشخاص الدخول ببريد العمل وكلمة مرور بعد التحقق من البريد. تنتظر التسجيلات الجديدة بحالة "قيد الاعتماد" حتى تمنحها القيادة دوراً أدناه. قاعدة البيانات تطبّق كل مستوى، فالمحتوى الذي لا يحق لدور ما رؤيته لا يصل إلى متصفحه أبداً.')}</p>
  <div class="note-info">${L('Signed in as','مسجل الدخول باسم')} <b>${esc(ME.email)}</b> · ${L('Your access','صلاحيتك')}: <b>${L(...ROLES[realRole])}</b></div>
  <div class="grid g4" style="margin-bottom:16px">${lv.map(([id,c,n,d])=>`<div class="card lvl" style="--c:${c}"><b style="color:${c};font-size:16px">${n}</b><p class="small" style="margin:6px 0 0">${d}</p></div>`).join('')}</div>
  <div class="card" style="padding:0;overflow:auto;margin-bottom:16px"><table class="matrix"><tr><th>${L('What they can do','ما يمكنهم فعله')}</th>${lv.map(x=>`<th>${x[2]}</th>`).join('')}</tr>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</table></div>
  ${realRole==='leadership'?`<div class="card" style="margin-bottom:16px"><h3 class="h3s">👥 ${L('People and roles','الأشخاص والأدوار')}</h3><div id="peopleBox" class="small muted">${L('Loading…','جارٍ التحميل…')}</div></div>
  <div class="grid g2" style="margin-bottom:16px"><div class="card"><h3 class="h3s">🔒 ${L('Who may sign up','من يحق له التسجيل')}</h3><p class="small muted" style="margin-top:0">${L('Only e-mail addresses on these domains can create an account. Leave empty to allow any address (everyone still starts as Pending).','فقط عناوين البريد على هذه النطاقات يمكنها إنشاء حساب. اتركها فارغة للسماح بأي عنوان (ويبدأ الجميع بحالة قيد الاعتماد).')}</p><div id="domBox"></div>
   <div style="display:flex;gap:8px;margin-top:8px"><input class="txt" id="newDom" placeholder="iih.com.sa" dir="ltr"><button class="btn primary" onclick="addDomain()">＋ ${L('Add','إضافة')}</button></div></div>
   <div class="card"><h3 class="h3s">📝 ${L('Content requests from presales','طلبات المحتوى من فريق ما قبل البيع')}</h3><div id="fbBox" class="small muted">${L('Loading…','جارٍ التحميل…')}</div></div></div>`:''}
  <div class="card" style="margin-bottom:16px;border-top:4px solid #25A27F"><h3 class="h3s">🔗 ${L('Client links (Product Showcase)','روابط العملاء (عرض المنتجات)')}</h3>
   <p class="small muted" style="margin-top:0">${L('A public page with client-safe content only — no sign-in. A single-product link opens straight on that product and hides the others.','صفحة عامة تحتوي على المحتوى المناسب للعملاء فقط — دون تسجيل دخول. رابط المنتج الواحد يفتح المنتج مباشرة ويخفي باقي المنتجات.')}</p>
   <div class="cl-row"><b>${L('All products','كل المنتجات')}</b><a href="${SHOWCASE}" target="_blank" rel="noopener">${SHOWCASE}</a><button class="btn mini" onclick="copyText('${SHOWCASE}')">⎘</button></div>
   ${PRODUCTS.map(p=>`<div class="cl-row"><b>${esc(p.name)}</b><span class="small muted" dir="ltr">${SHOWCASE}#only-${p.id}</span><button class="btn mini" onclick="copyText('${SHOWCASE}#only-${p.id}')">⎘</button></div>`).join('')}
   ${realRole==='leadership'?`<div style="margin:10px 0"><button class="btn green" onclick="exportShowcase()">⬇ ${L('Download updated showcase data (products.js)','تنزيل بيانات صفحة العرض المحدّثة (products.js)')}</button> <span class="small muted">${L('Replace showcase/js/products.js in the repository with this file to publish content changes to clients.','استبدل الملف showcase/js/products.js في المستودع بهذا الملف لنشر تحديثات المحتوى للعملاء.')}</span></div>`:''}
   <p class="small muted" style="margin-bottom:0">⚠ ${L('The Showcase is regenerated from the product content when you publish it (see README). Have the product owner verify content before sending a link to a client.','يُعاد إنشاء صفحة العرض من محتوى المنتجات عند نشرها (راجع README). اطلب من مالك المنتج اعتماد المحتوى قبل إرسال الرابط لأي عميل.')}</p></div>`;
}
/* Client-safe export: only these fields ever leave the hub for the public showcase */
function exportShowcase(){const clean=s=>String(s||'').replace(/\s*\((website claim|per website)\)/gi,'');
  const out=PRODUCTS.map(p=>{const ar=p.ar||{};return {id:p.id,name:p.name,short:p.short,color:p.color,logo:p.logo,family:p.brand==='orbit'?'orbit':'qiyas',cat:p.cat,tagline:p.tagline,pitch:p.pitch,elevator:p.elevator,keyMsg:p.keyMsg||'',journey:p.journey||null,
   ar:{cat:ar.cat||'',tagline:ar.tagline||'',pitch:ar.pitch||'',elevator:ar.elevator||[],keyMsg:ar.keyMsg||'',journey:ar.journey||null},
   features:p.features.map(f=>({f:f.f,b:f.b,p:clean(f.p)})),videos:p.videos.filter(v=>v.src).map(v=>({t:v.t,d:v.d,src:v.src,poster:v.poster,rtl:!!v.rtl,ch:v.ch||[]})),
   shots:(p.shots||[]).filter(s=>s.img).map(s=>({t:s.t,img:s.img,fit:s.fit||'cover',n:String(s.n).replace(/^Illustration from the explainer video.*$/,'Illustration')})),
   cases:(p.cases||[]).map(c=>({c:c.c.replace(/^Use case: /,''),o:c.o,r:c.r})),tech:(p.tech||[]).filter(([k])=>!/Not in production|MoC proposal/i.test(k)),faq:(p.rfp||[]).filter(r=>!/MoC proposal/i.test(r.q)).map(r=>({q:r.q,a:r.a}))}});
  saveBlob('products.js',new Blob(['const PRODUCTS='+JSON.stringify(out)+';\n'],{type:'text/javascript'}));toast(L('Downloaded — commit it to showcase/js/','تم التنزيل — ارفعه إلى showcase/js/'))}
async function loadAdmin(){if(realRole!=='leadership')return;
  let ppl=[],doms=[],fb=[];
  try{const [u,a,f]=await Promise.all([DB.collection('users').get(),DB.collection('config').doc('access').get(),DB.collection('feedback').orderBy('createdAt','desc').limit(50).get()]);
    ppl=u.docs.map(d=>({id:d.id,...d.data(),created_at:tsStr(d.data().createdAt),full_name:d.data().name})).sort((x,y)=>String(x.created_at).localeCompare(String(y.created_at)));
    doms=((a.exists&&a.data().domains)||[]).slice().sort().map(d=>({domain:d}));
    fb=f.docs.map(d=>({id:d.id,...d.data(),product_id:d.data().productId,created_at:tsStr(d.data().createdAt)}));
  }catch(e){const pb=document.getElementById('peopleBox');if(pb)pb.innerHTML=`<div class="note-warn">${esc(e.message)}</div>`;return}
  const pb=document.getElementById('peopleBox');if(!pb)return;
  const opts=r=>['pending','presales','lead','leadership'].map(x=>`<option value="${x}" ${x===r?'selected':''}>${x==='pending'?L('Pending (no access)','قيد الاعتماد (بدون وصول)'):L(...ROLES[x])}</option>`).join('');
  const pend=(ppl||[]).filter(p=>p.role==='pending').length;
  pb.innerHTML=`${pend?`<div class="note-warn">⏳ ${pend} ${L('person(s) waiting for a role','شخص بانتظار تعيين دور')}</div>`:''}<table class="users"><tr><th>${L('E-mail','البريد')}</th><th>${L('Name','الاسم')}</th><th>${L('Role','الدور')}</th><th>${L('Joined','تاريخ الانضمام')}</th><th></th></tr>${(ppl||[]).map(p=>`<tr><td dir="ltr">${esc(p.email)}</td><td>${esc(p.full_name||'')}</td><td>${p.id===ME.id?`<b>${L(...ROLES[p.role])}</b> <span class="muted">(${L('you','أنت')})</span>`:`<select class="txt" style="width:auto" onchange="setUserRole('${p.id}',this.value)">${opts(p.role)}</select>`}</td><td class="muted">${esc((p.created_at||'').slice(0,10))}</td><td>${p.id===ME.id?'':`<button class="btn mini" onclick="removeUser('${p.id}')">${L('Remove access','إزالة الوصول')}</button>`}</td></tr>`).join('')}</table>`;
  document.getElementById('domBox').innerHTML=(doms||[]).length?(doms||[]).map(d=>`<span class="pill" style="margin:2px">${esc(d.domain)} <a href="javascript:delDomain('${esc(d.domain)}')" style="color:#B23A3A;text-decoration:none">✕</a></span>`).join(''):`<span class="small muted">${L('Any e-mail domain may sign up.','يمكن لأي نطاق بريد التسجيل.')}</span>`;
  const fbB=document.getElementById('fbBox');const pn=id=>(PRODUCTS.find(p=>p.id===id)||{}).name||id;
  fbB.innerHTML=(fb||[]).length?(fb||[]).map(f=>`<div class="fb-row"><div style="flex:1"><b>${esc(pn(f.product_id))}</b> · <span class="muted">${esc(catName(CATS.find(c=>c.id===f.section)||{id:'overview',name:f.section}))}</span><div>${esc(f.message)}</div><span class="muted">${esc((f.created_at||'').slice(0,10))}</span></div><select class="txt" style="width:auto" onchange="setFb('${f.id}',this.value)">${['open','in_progress','done','rejected'].map(s=>`<option ${s===f.status?'selected':''} value="${s}">${({open:L('Open','مفتوح'),in_progress:L('In progress','قيد العمل'),done:L('Done','تم'),rejected:L('Rejected','مرفوض')})[s]}</option>`).join('')}</select></div>`).join(''):`<span class="small muted">${L('No requests yet.','لا توجد طلبات بعد.')}</span>`;}
async function setUserRole(id,r){try{await DB.collection('users').doc(id).update({role:r});toast(L('Role updated','تم تحديث الدور'))}catch(e){toast(L('Could not change role','تعذّر تغيير الدور'))}loadAdmin()}
/* Removing access sets the person back to Pending: their sign-in still works but they see nothing. Delete the login itself in Firebase console → Authentication if needed. */
async function removeUser(id){try{await DB.collection('users').doc(id).update({role:'pending'});toast(L('Access removed','تمت إزالة الوصول'))}catch(e){toast(L('Could not remove','تعذّرت الإزالة'))}loadAdmin()}
async function addDomain(){const d=$('#newDom').value.trim().toLowerCase().replace(/^@/,'');if(!/^[a-z0-9.-]+\.[a-z]{2,}$/.test(d))return toast(L('Enter a domain like iih.com.sa','أدخل نطاقاً مثل iih.com.sa'));
  try{await DB.collection('config').doc('access').set({domains:firebase.firestore.FieldValue.arrayUnion(d)},{merge:true});toast(L('Domain added','تمت إضافة النطاق'))}catch(e){toast(L('Could not add domain','تعذّرت إضافة النطاق'))}loadAdmin()}
async function delDomain(d){try{await DB.collection('config').doc('access').set({domains:firebase.firestore.FieldValue.arrayRemove(d)},{merge:true})}catch(e){}loadAdmin()}
async function setFb(id,s){try{await DB.collection('feedback').doc(id).update({status:s});toast(L('Updated','تم التحديث'))}catch(e){toast(L('Could not update','تعذّر التحديث'))}}
function feedbackForm(pid,sec){$('#mt').textContent=L('Report an issue or request content','الإبلاغ عن ملاحظة أو طلب محتوى');
  $('#mb').innerHTML=`<p class="muted" style="margin-top:0">${esc((PRODUCTS.find(p=>p.id===pid)||{}).name)} · ${esc(catName(CATS.find(c=>c.id===sec)))}</p><div class="field"><label>${L('What is missing or wrong?','ما الناقص أو الخاطئ؟')}</label><textarea class="txt" id="fbMsg" rows="4"></textarea></div><div style="display:flex;gap:8px;justify-content:flex-end"><button class="btn" onclick="closeModal()">${L('Cancel','إلغاء')}</button><button class="btn primary" onclick="sendFb('${pid}','${sec}')">${L('Send','إرسال')}</button></div>`;$('#modal').classList.add('show')}
async function sendFb(pid,sec){const m=$('#fbMsg').value.trim();if(m.length<3)return;let error=null;try{await DB.collection('feedback').add({productId:pid,section:sec,message:m,status:'open',createdBy:ME.id,createdByEmail:ME.email,createdAt:FBTS()})}catch(e){error=e}closeModal();toast(error?L('Could not send','تعذّر الإرسال'):L('Thanks — sent to the product owners','شكراً — تم الإرسال لمالكي المنتج'))}
function vSetup(){return `<h1>${L('How this works','آلية العمل')}</h1>
 <div class="card" style="margin-bottom:16px"><h3 class="h3s">${L('Architecture','البنية')}</h3><div class="arch"><div class="box2"><b>${L('Staff','الموظفون')}</b><span class="small muted">${L('Browser / mobile','المتصفح / الجوال')}</span></div><span class="arr">→</span><div class="box2"><b>GitHub Pages</b><span class="small muted">${L('Hub files (no internal content)','ملفات المركز (دون محتوى داخلي)')}</span></div><span class="arr">→</span><div class="box2"><b>Firebase Authentication</b><span class="small muted">${L('E-mail + password, verified e-mail','البريد وكلمة المرور مع التحقق من البريد')}</span></div><span class="arr">→</span><div class="box2"><b>Cloud Firestore</b><span class="small muted">${L('Products, leads, roles (security rules)','المنتجات والفرص والأدوار (قواعد الأمان)')}</span></div></div>
 <div class="arch"><div class="box2"><b>${L('Clients','العملاء')}</b><span class="small muted">${L('No sign-in','دون تسجيل')}</span></div><span class="arr">→</span><div class="box2"><b>/showcase</b><span class="small muted">${L('Client-safe content only','المحتوى المناسب للعملاء فقط')}</span></div></div></div>
 <div class="grid g2"><div class="card"><h3 class="h3s">${L('Where things are stored','أين تُحفظ البيانات')}</h3><ul class="small" style="padding-inline-start:18px;margin:0"><li><b>products</b> — ${L('all product content, Arabic summaries included; staff read, Leadership edits','كل محتوى المنتجات بما فيه الملخصات العربية؛ يقرؤه الموظفون وتعدّله القيادة')}</li><li><b>leads</b> — ${L('leads, contacts, timeline and scope; Leadership and Presales leads only','الفرص وجهات الاتصال والجدول الزمني والنطاق؛ للقيادة وقادة ما قبل البيع فقط')}</li><li><b>users</b> — ${L('who has which role','من يملك أي دور')}</li><li><b>feedback</b> — ${L('content requests from presales','طلبات المحتوى من فريق ما قبل البيع')}</li><li><b>config</b> — ${L('allowed sign-up domains, first-admin marker','نطاقات التسجيل المسموحة وعلامة أول مسؤول')}</li><li><b>contentReviews</b> — ${L('Draft / Verified status per product section','حالة مسودة / معتمد لكل قسم')}</li></ul></div>
 <div class="card"><h3 class="h3s">${L('Good to know','معلومات مهمة')}</h3><ul class="small" style="padding-inline-start:18px;margin:0"><li>${L('The GitHub Pages site is public, so it holds no internal content. Product details, leads and roles load from Firestore only after sign-in.','موقع GitHub Pages عام، لذا لا يحتوي على أي محتوى داخلي. تُحمَّل تفاصيل المنتجات والفرص والأدوار من Firestore بعد تسجيل الدخول فقط.')}</li><li>${L('Videos, logos and screenshots are public files in the repository.','الفيديوهات والشعارات واللقطات ملفات عامة في المستودع.')}</li><li>${L('Leads update live for everyone who has them open.','تتحدث الفرص مباشرة لكل من يفتحها.')}</li><li>${L('Free Spark plan: 50,000 reads and 20,000 writes a day — far more than a presales team needs.','الخطة المجانية Spark: 50,000 قراءة و20,000 كتابة يومياً — أكثر بكثير من حاجة فريق ما قبل البيع.')}</li></ul></div></div>${realRole==='leadership'?importBox():''}`;}

/* ============ HELPERS ============ */
function mock(k,c){ // simple illustrative UI screenshots (replace with real product images)
 const top=`<rect width="320" height="180" fill="#F7F9FB"/><rect width="320" height="22" fill="#0F2636"/><circle cx="10" cy="11" r="3" fill="#fff" opacity=".5"/><rect x="20" y="8" width="50" height="6" rx="3" fill="#fff" opacity=".5"/>`;
 let b='';
 if(k==='chat') b=`<rect x="0" y="22" width="70" height="158" fill="#EEF2F5"/>${[0,1,2,3].map(i=>`<rect x="8" y="${34+i*16}" width="54" height="7" rx="3" fill="#CCD5DD"/>`).join('')}<rect x="170" y="34" width="135" height="22" rx="8" fill="${c}"/><rect x="82" y="64" width="190" height="52" rx="8" fill="#fff" stroke="#E2E7EC"/><rect x="90" y="72" width="160" height="6" rx="3" fill="#CCD5DD"/><rect x="90" y="84" width="140" height="6" rx="3" fill="#CCD5DD"/><rect x="90" y="98" width="60" height="10" rx="5" fill="#F6EED9"/><rect x="82" y="150" width="225" height="20" rx="10" fill="#fff" stroke="#E2E7EC"/>`;
 else if(k==='dash') b=`${[0,1,2,3].map(i=>`<rect x="${10+i*77}" y="32" width="70" height="36" rx="6" fill="#fff" stroke="#E2E7EC"/><rect x="${17+i*77}" y="40" width="30" height="5" rx="2" fill="#CCD5DD"/><rect x="${17+i*77}" y="51" width="40" height="9" rx="2" fill="${i%2?'#0F2636':c}"/>`).join('')}<rect x="10" y="76" width="190" height="96" rx="6" fill="#fff" stroke="#E2E7EC"/><polyline points="20,155 50,140 80,145 110,120 140,125 170,100 190,92" fill="none" stroke="${c}" stroke-width="3"/><rect x="208" y="76" width="102" height="96" rx="6" fill="#fff" stroke="#E2E7EC"/>${[0,1,2,3,4].map(i=>`<rect x="218" y="${88+i*16}" width="${30+((i*23)%60)}" height="8" rx="3" fill="${i===0?c:'#CCD5DD'}"/>`).join('')}`;
 else b=`<rect x="10" y="32" width="300" height="18" rx="4" fill="#E2E7EC"/>${[0,1,2,3,4,5].map(i=>`<rect x="10" y="${56+i*19}" width="300" height="15" rx="3" fill="#fff" stroke="#EEF2F5"/><rect x="16" y="${61+i*19}" width="80" height="5" rx="2" fill="#CCD5DD"/><rect x="120" y="${61+i*19}" width="100" height="5" rx="2" fill="#E2E7EC"/><rect x="262" y="${59+i*19}" width="38" height="9" rx="4" fill="${i%3?'#E3F3EA':'#FBE6DE'}"/>`).join('')}`;
 return `<svg viewBox="0 0 320 180" style="display:block;width:100%">${top}${b}</svg>`;
}
function openShot(pid,k,t,isVid){const p=PRODUCTS.find(x=>x.id===pid);$('#mt').textContent=t;$('#mb').innerHTML=`<div style="position:relative">${mock(k,p.color)}${isVid?'<div style="position:absolute;inset:0;display:grid;place-items:center;color:#fff;background:rgba(15,38,54,.55);font-size:15px;text-align:center;padding:20px">Video player — in the live version this plays from Stream / SharePoint or storage</div>':''}</div><p class="small muted">Sample illustration. Replace with real product ${isVid?'video':'screenshot'}. Add notes for presales: what to point out and which persona cares.</p>`;$('#modal').classList.add('show');}
function openImg(pid,i){const s=PRODUCTS.find(x=>x.id===pid).shots[i];$('#mt').textContent=s.t;$('#mb').innerHTML=`<img src="${s.img}" style="width:100%;border-radius:8px"><p class="small muted">${esc(s.n)}</p>`;$('#modal').classList.add('show');}
function seek(i,t){const v=document.getElementById('vid'+i);if(!v)return;try{v.currentTime=t;v.play().catch(()=>{})}catch(e){}}
function closeModal(){$('#modal').classList.remove('show');$('#mb').querySelectorAll('video').forEach(v=>v.pause())}
function addProduct(){$('#mt').textContent='Add a product';$('#mb').innerHTML=`<div class="field"><label>Product name</label><input class="txt" id="np" placeholder="e.g. IIH Smart Archive"></div><div class="field"><label>One-line tagline</label><input class="txt" id="nt" placeholder="What it does, for whom"></div><p class="small muted">The 12 presales categories are created automatically and start empty, so the readiness score shows the owner what is missing.</p><div style="text-align:right"><button class="btn primary" onclick="newProd()">Create product tab</button></div>`;$('#modal').classList.add('show');}
function newProd(){const n=$('#np').value.trim();if(!n)return;const id='p'+Date.now().toString(36);PRODUCTS.push({id,name:n,short:n.slice(0,18),color:'#1B3A50',ini:n.slice(0,2).toUpperCase(),status:'Draft',owner:'Unassigned',ready:5,tagline:$('#nt').value||'Tagline to be written',pitch:'Pitch to be written.',elevator:[],personas:[],icp:{size:'—',sector:'—',trigger:'—',budget:'—'},pains:[],features:[],videos:[],shots:[],demoScript:[],cases:[],comp:[],obj:[],tiers:[],disc:'',tech:[],rfp:[]});closeModal();go('product',id);toast('Product tab created (demo — not saved)');}
function copyText(t,m){try{navigator.clipboard.writeText(t).then(()=>toast(m||'Copied'),()=>toast('Select and copy manually'))}catch(e){toast('Select and copy manually')}}
let tt;function toast(m){const e=$('#toast');e.textContent=m;e.classList.add('show');clearTimeout(tt);tt=setTimeout(()=>e.classList.remove('show'),2200)}
function doSearch(v){v=v.trim().toLowerCase();if(v.length<2){sr.style.display='none';return}const hits=[];
 PRODUCTS.forEach(p=>{const add=(cat,txt)=>{if(txt.toLowerCase().includes(v))hits.push({p,cat,txt})};
  add('overview',p.pitch);p.features.forEach(f=>add('features',f.f+' — '+f.b));p.obj.forEach(o=>add('objections',o.o));p.comp.forEach(c=>add('compete','vs '+c.x));p.cases.forEach(c=>add('cases',c.c+' — '+c.o));p.rfp.forEach(r=>add('assets',r.q));p.pains.forEach(x=>add('pains',x.q));p.videos.forEach(x=>add('demo',x.t));p.tech.forEach(t=>add('tech',t[0]+': '+t[1]));});
 sr.innerHTML=hits.slice(0,12).map(h=>`<div onmousedown="go('product','${h.p.id}','${h.cat}');sr.style.display='none';$('#q').value=''"><b>${esc(h.txt.slice(0,90))}</b><br><span>${esc(h.p.short)} · ${catName(CATS.find(c=>c.id===h.cat))}</span></div>`).join('')||'<div><span>No results</span></div>';sr.style.display='block';}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
function startApp(r){window._appStarted=true;realRole=r;role=r;applyLang();document.body.classList.toggle('admin',role==='leadership');document.body.classList.toggle('client',role==='client');fromHash();}
